package com.linebook.agent.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A collection agent (the front end's Agent: id, name, phone, area) plus an active flag. */
@Entity
@Table(name = "agents")
public class Agent {

    @Id
    @Column(name = "id", length = 64, nullable = false, updatable = false)
    private String id;

    /** Creation order; generated by MySQL (AUTO_INCREMENT), read-only here. */
    @Column(name = "seq", insertable = false, updatable = false)
    private Long seq;

    @Column(name = "name", length = 150, nullable = false)
    private String name;

    @Column(name = "phone", length = 15, nullable = false)
    private String phone;

    @Column(name = "area", length = 100, nullable = false)
    private String area;

    @Column(name = "active", nullable = false)
    private boolean active;

    protected Agent() {
        // JPA
    }

    public Agent(String id, String name, String phone, String area, boolean active) {
        this.id = id;
        this.name = name;
        this.phone = phone;
        this.area = area;
        this.active = active;
    }

    public void changeDetails(String name, String phone, String area) {
        this.name = name;
        this.phone = phone;
        this.area = area;
    }

    public void changeActive(boolean active) {
        this.active = active;
    }

    public String getId() { return id; }
    public Long getSeq() { return seq; }
    public String getName() { return name; }
    public String getPhone() { return phone; }
    public String getArea() { return area; }
    public boolean isActive() { return active; }
}
